const TWO_DAY_TICKET_TEXT = "Två dagar??? (Vad? 12:00 - 19:00)";
const DAYS_TO_HAVE_TWO_DAY_TICKETS = ["28", "29"];
const DAY_TO_HAVE_TWO_DAY_TICKETS = DAYS_TO_HAVE_TWO_DAY_TICKETS[0];
export const TwoDayTickets: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    //Wait for 1 seconds to make sure the purchase flow is loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    await clickElementWithTestId(canvas, "increase-button-Vuxen");
    await clickElementWithTestId(canvas, "group-size-next-button");

    const dayForTwoDayTickets = canvas.getByText(DAY_TO_HAVE_TWO_DAY_TICKETS);

    //Expect to see the two day ticket variant when the date has been clicked on
    await userEvent.click(dayForTwoDayTickets);
    const variantForTwoDayTickets = canvas.getByText(TWO_DAY_TICKET_TEXT);
    await expect(variantForTwoDayTickets).toBeInTheDocument();

    //Expect to see the chosen dates with the marker in the calendar when the two day ticket variant has been clicked on
    await userEvent.click(variantForTwoDayTickets);
    const selector = "td[data-selected=true] *"; // This makes sure we only get elements inside selected dates
    expect(canvas.getByText(DAYS_TO_HAVE_TWO_DAY_TICKETS[0], { selector })).toBeInTheDocument();
    expect(canvas.getByText(DAYS_TO_HAVE_TWO_DAY_TICKETS[1], { selector })).toBeInTheDocument();
  },
  args: {
    ...Primary.args,
    stepConfigOverride: {
      ...Primary.args?.stepConfigOverride,
      selectTicketInsteadOfVariant: false,
    },
  },
  render: (args) => {
    return (
      <GroupAdmissionStory
        key="TwoDays"
        getPurchaseFlow={async () => {
          const response = await fetch("/mock-data/purchase-flow-glt-prod.json");
          return await response.json();
        }}
        args={args}
      />
    );
  },
};

/**
 * We test to assert that if we have an event on a sold out date, we actually display the sold out content.
 * The date to be sold out will be the 29th of April 2025.
 * The product to be sold out will be Adult P2.
 * The quantity will be set to 3, but the user will try to add 4 tickets to the cart.
 */
const SOLD_OUT_TEXT = "Slutsålt? Lugn!";
const SOLD_OUT_TEXT_BUTTON = "Köp Grönan Live-passet";
const DATE_TO_BE_SOLD_OUT = "2025-04-30";
const DAY_TO_BE_SOLD_OUT = DATE_TO_BE_SOLD_OUT.substring(8, 10);
const NEW_QUANTITY_FOR_DATE = 3;
export const ShowSoldOutEventDateContent: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    //Wait for 1 seconds to make sure the purchase flow is loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    //Try to buy more than available
    for (let i = 0; i < NEW_QUANTITY_FOR_DATE + 1; i++) {
      await clickElementWithTestId(canvas, "increase-button-Vuxen");
    }

    await clickElementWithTestId(canvas, "group-size-next-button");

    const buttonForSoldOutDate = canvas.getByText(DAY_TO_BE_SOLD_OUT);

    //A new requirement is that the day should *NOT* be disabled when sold out (if there is an event)
    expect(buttonForSoldOutDate.parentElement?.className).not.toEqual(expect.stringMatching(/unavailable/));

    //Expect to see the sold out content when the date has been clicked on
    await userEvent.click(buttonForSoldOutDate);
    await expect(canvas.getByText(SOLD_OUT_TEXT)).toBeInTheDocument();
    await expect(canvas.getByText(SOLD_OUT_TEXT_BUTTON)).toBeInTheDocument();
  },
  args: {
    mockedDate: new Date("2025-03-12 17:00:55"),
    groupAdmission: "GLT 2025",
    soldOutEventDateContent: {
      //This is the content that will be displayed when the user tries to add more tickets than there are available
      raw: JSON.stringify({
        data: {},
        content: [
          {
            data: {},
            content: [{ data: {}, marks: [], value: SOLD_OUT_TEXT, nodeType: "text" }],
            nodeType: "heading-3",
          },
          {
            data: { target: { sys: { id: "52nUmTBbx7o9IqJtX30U4d", type: "Link", linkType: "Entry" } } },
            content: [],
            nodeType: "embedded-entry-block",
          },
          { data: {}, content: [{ data: {}, marks: [], value: "", nodeType: "text" }], nodeType: "paragraph" },
        ],
        nodeType: "document",
      }),
      references: [
        {
          __typename: "ContentfulLink",
          contentful_id: "52nUmTBbx7o9IqJtX30U4d",
          id: "a6c4d6d0-18ea-51d9-9c28-b02ee19fb36e",
          title: SOLD_OUT_TEXT_BUTTON,
          smallDeviceTitle: SOLD_OUT_TEXT_BUTTON,
          internalLink: null,
          externalUrl: "https://gronalund.com/biljetter/grona-kortet-flow",
          openInNewTab: null,
          image: null,
          asset: null,
          linkIcon: null,
          scrollToBlockTitle: null,
          scrollToBlock: null,
        },
      ],
    },
    purchaseFlowId: PURCHASE_FLOW_ID,
    showConcertsInCalendar: true,
    hideParkOpeningTimes: false,
    stepConfigOverride: {
      ...TwoDayTickets.args?.stepConfigOverride,
    },
  },
  render: (args) => {
    return (
      <GroupAdmissionStory
        key="ShowSoldOutEventDateContent"
        getPurchaseFlow={async () => {
          const response = await fetch("/mock-data/purchase-flow-glt-prod.json");
          const purchaseFlow = (await response.json()) as PurchaseFlowResponse;
          //Modify to reduce the date slot quantity to 3 for the 29th of April 2025 where the product is Adult P2
          return {
            ...purchaseFlow,
            calendar: purchaseFlow.calendar.map((calendarDateResponse) => {
              if (calendarDateResponse.date !== `${DATE_TO_BE_SOLD_OUT}T00:00:00`) {
                return calendarDateResponse;
              }
              return {
                ...calendarDateResponse,
                products: calendarDateResponse.products.map((product) => {
                  if (product.productName !== "Ticket-to-ride Dag 10-64 P2") {
                    return product;
                  }
                  return {
                    ...product,
                    dateSlot: {
                      ...product.dateSlot,
                      quantity: NEW_QUANTITY_FOR_DATE,
                    },
                  };
                }),
              };
            }),
          } satisfies PurchaseFlowResponse;
        }}
        //We need to mock the showsForPurchaseFlow and eventsForShowIds to make sure we have an event on the 29th of April 2025
        showsForPurchaseFlow={[
          {
            contentful_id: "contentful-1",
            id: "event-1",
            node_locale: "sv",
            internalTitle: "Konsert 1",
            title: "Konsert 1",
            showInPurchaseFlow: true,
          },
        ]}
        eventsForShowIds={[
          {
            id: "event-1",
            title: "Konsert 1",
            location: "Stora scen",
            pageLink: { slug: "/konsert-1" },
            product: { productPageLink: { slug: "/konsert-1" }, contentful_id: "some-contentful-id" },
            imageInList: {
              file: {
                url: "https://images.ctfassets.net/ds6dz7ilx8up/1COUx8h7qwxEazvqH7eci1/da4f7c68a377a52c753911eed0cfce27/samiroviktor-mobile.jpg",
              },
            },
            events: [
              {
                title: "Konsert 1",
                startDateAndTime: new Date(`${DATE_TO_BE_SOLD_OUT}T18:00+02:00`),
                endDateAndTime: new Date(`${DATE_TO_BE_SOLD_OUT}T20:00+02:00`),
                cancelled: false,
                cancelledText: "Inställt",
                id: "event-1",
                description: "Konsert 1",
                showId: "event-1",
              },
            ],
            contentful_id: "event-1",
            node_locale: "sv",
            internalTitle: "Konsert 1",
          },
        ]}
        args={args}
      />
    );
  },
};

